// Credentials for git hosts other than the GitHub App: HTTPS access tokens
// and SSH deploy keys (pasted or generated by the panel), with known_hosts
// for SSH hosts. Secrets are stored sealed and never returned; services
// pick a credential by id in their source.

import { Type } from "@sinclair/typebox";
import { defineOp } from "../define";
import { permission } from "../permission";
import { Empty, GitUrl, Id, Timestamp } from "../schemas";

export const GitHost = Type.String({
  minLength: 1,
  maxLength: 253,
  pattern: "^[A-Za-z0-9.-]+(:[0-9]{1,5})?$",
  description: 'Host the credential is for, for example "gitlab.com" or "git.example.com:2222".',
});

const CredentialName = Type.String({ minLength: 1, maxLength: 60 });
const KnownHosts = Type.String({ maxLength: 20_000, description: "known_hosts lines; empty uses the built-in keys of well-known hosts." });
const PrivateKey = Type.String({ minLength: 1, maxLength: 20_000, pattern: "^-----BEGIN [A-Z ]*PRIVATE KEY-----" });

export const GitCredential = Type.Object({
  id: Id,
  name: CredentialName,
  kind: Type.Union([Type.Literal("token"), Type.Literal("ssh_key")]),
  host: GitHost,
  /** HTTPS user name for tokens; some hosts need one. */
  username: Type.Union([Type.String(), Type.Null()]),
  /** OpenSSH public key of an SSH credential, to add as a deploy key on the host. */
  publicKey: Type.Union([Type.String(), Type.Null()]),
  /** SHA256 fingerprint of the SSH key. */
  fingerprint: Type.Union([Type.String(), Type.Null()]),
  knownHosts: Type.String(),
  /** "device" = the GitHub account connected with the device flow (github.deviceStart). */
  origin: Type.Union([Type.Literal("manual"), Type.Literal("generated"), Type.Literal("device")]),
  /** Services whose source uses it. */
  usedBy: Type.Integer({ minimum: 0 }),
  createdAt: Timestamp,
  updatedAt: Timestamp,
});

export const listCredentials = defineOp({
  id: "git.listCredentials",
  kind: "query",
  summary: "List git credentials",
  description:
    "Lists stored git credentials by name, host and kind (never the secret), so people can pick one for a service's source. Empty for callers who may create or edit services nowhere.",
  input: Type.Object({}),
  output: Type.Object({ items: Type.Array(GitCredential, { description: "The stored git credentials, without secrets." }) }),
  // Names and hosts only, for people who may set a source somewhere (services.create or services.update).
  permission: permission.signedIn(),
  mcp: true,
  audit: false,
});

export const createCredential = defineOp({
  id: "git.createCredential",
  kind: "mutation",
  summary: "Add a git credential",
  description:
    "Stores an HTTPS access token (kind token) or an SSH private key (kind ssh_key) for a git host, sealed. To have the panel make the key pair instead, use git.generateSshKey.",
  input: Type.Object({
    name: CredentialName,
    kind: Type.Union([Type.Literal("token"), Type.Literal("ssh_key")]),
    host: GitHost,
    username: Type.Optional(Type.String({ maxLength: 100 })),
    /** Required for kind token. */
    token: Type.Optional(Type.String({ minLength: 1, maxLength: 1000 })),
    /** Required for kind ssh_key; OpenSSH or PEM, without a passphrase. */
    privateKey: Type.Optional(PrivateKey),
    knownHosts: Type.Optional(KnownHosts),
  }),
  output: GitCredential,
  permission: permission.global("git.manage"),
  sensitive: { input: ["token", "privateKey"] },
  mcp: false,
  audit: true,
});

export const generateSshKey = defineOp({
  id: "git.generateSshKey",
  kind: "mutation",
  summary: "Generate an SSH deploy key",
  description:
    "Makes a new Ed25519 key pair for a git host and stores the private key sealed. Add the returned public key as a read-only deploy key on the repository.",
  input: Type.Object({ name: CredentialName, host: GitHost, knownHosts: Type.Optional(KnownHosts) }),
  output: GitCredential,
  permission: permission.global("git.manage"),
  mcp: true,
  audit: true,
});

export const updateCredential = defineOp({
  id: "git.updateCredential",
  kind: "mutation",
  summary: "Change a git credential",
  description:
    "Renames a credential, or replaces its user name, secret or known_hosts. Omitted fields keep their value; the kind cannot change.",
  input: Type.Object({
    credentialId: Id,
    name: Type.Optional(CredentialName),
    username: Type.Optional(Type.Union([Type.String({ maxLength: 100 }), Type.Null()])),
    token: Type.Optional(Type.String({ minLength: 1, maxLength: 1000 })),
    privateKey: Type.Optional(PrivateKey),
    knownHosts: Type.Optional(KnownHosts),
  }),
  output: GitCredential,
  permission: permission.global("git.manage"),
  sensitive: { input: ["token", "privateKey"] },
  mcp: false,
  audit: true,
});

export const deleteCredential = defineOp({
  id: "git.deleteCredential",
  kind: "destructive",
  summary: "Delete a git credential",
  description: "Deletes a git credential. Fails while a service's source still uses it.",
  input: Type.Object({ credentialId: Id }),
  output: Empty,
  permission: permission.global("git.manage"),
  mcp: true,
  audit: true,
});

export const scanHostKeys = defineOp({
  id: "git.scanHostKeys",
  kind: "query",
  summary: "Read a host's SSH keys",
  description:
    "Connects to a git host over SSH (like ssh-keyscan) and returns its host keys as known_hosts lines with fingerprints, so a person can compare them before trusting them.",
  input: Type.Object({ host: GitHost }),
  output: Type.Object({ lines: Type.Array(Type.String()), fingerprints: Type.Array(Type.String()) }),
  permission: permission.global("git.manage"),
  mcp: true,
  audit: false,
});

export const branches = defineOp({
  id: "git.branches",
  kind: "query",
  summary: "List a git repository's branches",
  description:
    "Checks access to a git URL (with a stored credential for private repos, like git ls-remote) and lists its branches with the default one. Used to validate a generic git source before saving it. The host follows the rule for saving a source: a public address, an internal host an admin already saved a source with in this project, or any internal host for a git.manage caller; never a cloud metadata address (BAD_REQUEST internalTarget otherwise).",
  input: Type.Object({
    projectId: Id,
    url: GitUrl,
    credentialId: Type.Optional(Id),
  }),
  output: Type.Object({ branches: Type.Array(Type.String()), defaultBranch: Type.Union([Type.String(), Type.Null()]) }),
  permission: permission.project("services.create", (input: { projectId: string }) => input.projectId),
  mcp: true,
  audit: false,
});

export const allowInternalHost = defineOp({
  id: "git.allowInternalHost",
  kind: "mutation",
  summary: "Allow an internal git host in a project",
  description:
    "Lets the project's nodes clone from internal addresses (private, loopback, link-local, the node's own and the like) of the host of this git URL, whatever the panel's own DNS answers for it: for a git server whose name is public at the panel and internal at the nodes (split-horizon DNS). Saving a source as an admin does this by itself only when the panel sees the host as internal (a host on one of the nodes' own addresses counts). Also for a LAN-only name the panel cannot resolve (the first-start seed of 0.2 does not record those), and for a node behind an HTTP proxy that cannot resolve the git host itself (or that node's root sets git_proxy_resolves in its config.yml). git.listInternalHosts lists them, git.removeInternalHost takes one off. The project's members may then use the host in their sources and git.branches. Nodes still clone only that host and port from an internal address, never a redirect or submodule to another one, and never a cloud metadata address (BAD_REQUEST internalTarget).",
  input: Type.Object({ projectId: Id, url: GitUrl }),
  output: Type.Object({
    host: Type.String({ description: 'The host as recorded for the project, for example "gitea.lan" or "10.0.0.7:3000".' }),
  }),
  permission: permission.global("git.manage"),
  mcp: true,
  audit: true,
});

export const InternalGitHost = Type.String({
  minLength: 1,
  maxLength: 260,
  pattern: "^[A-Za-z0-9.:\\[\\]-]+$",
  description: 'A host as recorded for a project, for example "gitea.lan", "10.0.0.7:3000" or "[fd00::7]:3000".',
});

export const listInternalHosts = defineOp({
  id: "git.listInternalHosts",
  kind: "query",
  summary: "List a project's internal git hosts",
  description:
    "Lists the git hosts a project's nodes may clone from internal addresses (private, loopback, link-local, a node's own and the like): recorded when an admin saved a source with an internal host there, by git.allowInternalHost, or by the first start of 0.2 for sources saved before. approvedBy is null for hosts the first start recorded (or whose admin account is gone); usedBy counts the project's sources that clone from the host: generic git and compose stack git sources by URL, GitHub sources as github.com, and git provider sources by their connection's host.",
  input: Type.Object({ projectId: Id }),
  output: Type.Object({
    items: Type.Array(
      Type.Object({
        host: InternalGitHost,
        approvedBy: Type.Union([Type.Object({ id: Id, name: Type.String() }), Type.Null()]),
        createdAt: Timestamp,
        usedBy: Type.Integer({ minimum: 0 }),
      }),
    ),
  }),
  permission: permission.global("git.manage"),
  mcp: true,
  audit: false,
});

export const removeInternalHost = defineOp({
  id: "git.removeInternalHost",
  kind: "mutation",
  summary: "Stop allowing an internal git host in a project",
  description:
    "Takes a host off a project's internal git hosts: its nodes then clone it from public addresses only (not their own), so builds of the project's sources on a host the panel sees as internal fail until an admin saves one or allows it again (git.allowInternalHost). NOT_FOUND when the host is not allowed in the project.",
  input: Type.Object({ projectId: Id, host: InternalGitHost }),
  output: Empty,
  permission: permission.global("git.manage"),
  mcp: true,
  audit: true,
});
